import { ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case ACTIONS.GET_CATALOG:
    case ACTIONS.SUBMIT_CATALOG:
      return { ...state, ...payload }
    case ACTIONS.RESET_REDUX_STATE_CATALOG:
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = INITIAL_STATE[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    default:
      return state
  }
}

export default reducer
