import React from "react";
import {
  Input,
  Form,
  DatePicker,
  Radio,
  Select,
  InputNumber,
  Checkbox,
  TreeSelect,
} from "antd";
const { TreeNode } = TreeSelect;

export function getFormItems(formData) {
  const {
    form,
    placeHolder = "",
    disableField = false,
    type,
    label = " ",
    initialValue = "",
    required = false,
    className = " ",
    extra = "",
    loading = false,
    message = "",
    help = "",
  } = formData;
  // console.log(formData)
  const { getFieldDecorator } = form;

  switch (type) {
    case "numeric":
      return (
        <Form.Item>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: message,
              },
              // { validator: formData.validator }
            ],
            initialValue: initialValue,
          })(
            <InputNumber
              className={className}
              disabled={disableField}
              placeholder={placeHolder}
            />
          )}
        </Form.Item>
      );
    case "String":
      return (
        <Form.Item extra={extra} help={help} label={label}>
          {/* {label} */}

          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: message,
              },
            ],
            initialValue: initialValue,
          })(
            <Input
              className={className}
              disabled={disableField}
              placeholder={placeHolder}
            />
          )}
        </Form.Item>
      );
    case "alphanumeric":
      return (
        <Form.Item extra={extra} help={help}>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: message,
              },
              // { validator: formData.validator }
            ],
            initialValue: initialValue,
          })(
            <Input
              className={className}
              disabled={disableField}
              placeholder={placeHolder}
            />
          )}
        </Form.Item>
      );
    case "textarea":
      return (
        <Form.Item>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: "",
              },
              // { validator: formData.validator }
            ],
            initialValue: initialValue,
          })(
            <Input.TextArea
              rows={formData.row || 4}
              className={className}
              placeholder={""}
            />
          )}
        </Form.Item>
      );
    case "dob":
      return (
        <Form.Item>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: "",
              },
              // { validator: formData.validator }
            ],
            initialValue: initialValue,
          })(
            <DatePicker
              className={className}
              format={"YYYY-MM-DD"}
              placeholder={""}
              // disable selection above today
            />
          )}
        </Form.Item>
      );
    case "email":
      return (
        <Form.Item>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              { required: true, message: "" },
              { type: "email", message: "" },
            ],
            initialValue: initialValue,
          })(
            <Input
              className={className}
              disabled={!!initialValue}
              placeholder={""}
            />
          )}
        </Form.Item>
      );
    case "radio":
      return (
        <Form.Item>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: "Please Select Change Type Option",
              },
              // { validator: formData.validator }
            ],
            initialValue: initialValue,
          })(
            <Radio.Group>
              {formData.options.map((option, index) => {
                return (
                  <Radio key={index} value={option}>
                    {option}
                  </Radio>
                );
              })}
            </Radio.Group>
          )}
        </Form.Item>
      );
    case 'multi-choices':
      return (
        <Form.Item label={label}>
          
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: "",
              },
            ],
            initialValue: initialValue,
          })(
            <Select
              showSearch
              allowClear
              mode="multiple"
              disabled={disableField}
              dropdownMatchSelectWidth={false}
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            >
              {
                formData.options.map((item, idx) =>
                  <Select value={item} key={idx}>
                    {item}
                  </Select>)
              }
            </Select>
          )}
        </Form.Item>
      );
    case "choices":
      return (
        <Form.Item>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: "",
              },
            ],
            initialValue: initialValue,
          })(
            <Select
              showSearch
              allowClear
              dropdownMatchSelectWidth={false}
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            >
              {
                formData.options.map((item, idx) =>
                 <Select.Option value={item} key={idx}>
                   {item}
                </Select.Option>)
              }
            </Select>
          )}
        </Form.Item>
      );
    case "Boolean":
      return (
        <Form.Item>
          
          {getFieldDecorator(formData.formName, {
              
              rules: [
                {
                  required: required,
                  message: "",
                },
              ],
              valuePropName: "checked",
              initialValue: initialValue !== "" ? initialValue : false,
            })(<Checkbox>{label}</Checkbox>)
          }
            
        </Form.Item>
      );
    case "nested-tree-select":
      return (
        <Form.Item>
          {label}
          {getFieldDecorator(formData.formName, {
            rules: [
              {
                required: required,
                message: "",
              },
              // { validator: formData.validator }
            ],
            initialValue: initialValue,
          })(
            <TreeSelect
              // disabled={disableField}
              className={className}
              placeholder={""}
              treeDefaultExpandAll
              disabled={disableField}
              loading={loading}
            >
              {childNode(formData.options)}
            </TreeSelect>
          )}
        </Form.Item>
      );
    default:
      return null;
  }
}

export function childNode(data = []) {
  if (Array.isArray(data)) {
    return data.map((item, index) => {
      if (item.nested.length === 0) {
        const data = (
          <div>
            <span className="main-text">{item.name}</span> <br />
            {item.attribute_type && (
              <span className="sub-text">({item.attribute_type})</span>
            )}
          </div>
        );
        return <TreeNode value={item.id} title={data} />;
      } else {
        return <TreeNode title={item.name}>{childNode(item.nested)}</TreeNode>;
      }
    });
  }
}

export const decorateLabel = (str) => {
  var i,
    frags = str.split("_");
  for (i = 0; i < frags.length; i++) {
    frags[i] = frags[i].charAt(0).toUpperCase() + frags[i].slice(1);
  }
  return frags.join(" ");
};
