/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useCallback } from "react";
import { Form, Spin, notification, Button, Select } from "antd";
import QueryString from "query-string";
import {
  useLoaderContextValue,
  useErrorContextValue,
  resetError,
} from "@pasarpolis/common-react-hooks";
import LayoutContentWrapper from "../../../../../components/utility/layoutWrapper";
import {
  useGetCatalogData,
  useSubmitCatalog,
} from "../../state/hooks/useCatalogContext";
import GetIdForm from "../../components/GetIdForm";
import CatalogWrapper from "./style";
import { getFormItems, decorateLabel } from "../../formItems";

function DataCatalogForm({ location, form }) {
  const [{ getCatalogData = {} } , getCatalogDataRequest] = useGetCatalogData();
  const [, submitCatalogRequest] = useSubmitCatalog();
  const [isLoading, setIsLoading] = useState(true);
  const [renderIdForm, setRenderIdForm] = useState(true);
  //const [fetchId, setFetchId] = useState({});


  const [{ GET_CATALOG_LOADER }] = useLoaderContextValue();
  const [
    { GET_CATALOG_ERROR = "", getCatalogStatus = "", getCatalogErrorData = "", SUBMIT_CATALOG_ERROR, submitCatalogStatus, submitCatalogErrorData },
    dispatchError,
  ] = useErrorContextValue();

  //Fetching Id's from url
  useEffect(() => {
    const querySearch = QueryString.parse(location?.search);
    const { metadata_id: metadataID, validation_id: validationId } =
      querySearch;

    if (metadataID && validationId) {
      setIsLoading(false);      
      fetch(metadataID, validationId);
    } else {
      setIsLoading(false);
    }
  }, []);

  //Handling Error
  useEffect(() => {
    if (GET_CATALOG_ERROR) {
      const { error } = getCatalogErrorData;
      if (error) {
        notification.error({
          message: error || 'Failed to Fetch Data',
        });
      } else {
        getCatalogStatus &&
          notification.error({
            message: getCatalogStatus || 'Failed to Fetch Data',
          });
      }
      dispatchError(
        resetError({
          GET_CATALOG_ERROR: false,
          getCatalogStatus: "",
          getCatalogErrorData: "",
        })
      );
    } else if (!GET_CATALOG_ERROR && getCatalogStatus === "success") {
      getCatalogStatus &&
        notification.success({
          message: getCatalogStatus,
        });
      setRenderIdForm(false);
      dispatchError(
        resetError({
          GET_CATALOG_ERROR: false,
          getCatalogStatus: "",
          getCatalogErrorData: "",
        })
      );
    }
  }, [GET_CATALOG_ERROR, getCatalogStatus, getCatalogErrorData]);

  useEffect(() => {
    if (SUBMIT_CATALOG_ERROR){
      const { error } = submitCatalogErrorData
      if(error){
        notification.error({
          message: error
        })
      } else {
        submitCatalogStatus && notification.error({
          message: submitCatalogStatus
        })
      }
      dispatchError(
        resetError({
          SUBMIT_CATALOG_ERROR: false,
          submitCatalogErrorData: "",
          submitCatalogStatus: "",
        })
      ) 
    }
    else if (!SUBMIT_CATALOG_ERROR && submitCatalogStatus === "success") {
      submitCatalogStatus && notification.success({
        message: submitCatalogStatus
      })
      dispatchError(
        resetError({
          SUBMIT_CATALOG_ERROR: false,
          submitCatalogErrorData: "",
          submitCatalogStatus: "",
        })
      ) 
    }
  }, [SUBMIT_CATALOG_ERROR, submitCatalogStatus, submitCatalogErrorData])

  const fetch = useCallback((metaId, validationId) => {
    getCatalogDataRequest({
      query: {
        meta_data: metaId,
        validation_id: validationId,
      },
    });
  }, []);

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error);
      });
    });
  }, [form]);

  const submitForm = (payload) => {

    submitCatalogRequest({
      body: {
        ...payload,
        metadata_id: getCatalogData?.hidden_fields?.metadata_id,
        validation_id: getCatalogData?.hidden_fields?.validation_id,
      },
    });
  }

  const handleSubmit = useCallback(
    async (e) => {
      e.preventDefault();
      const valid = await validateForm();
      if (!valid) return;
      const formValues = {
        ...form.getFieldsValue(),
      };


      if (form.getFieldValue("type.change_type") === "Renamed"){
        submitForm({ 
          ...formValues, 
          type : {
            ...formValues.type,
            old_value_metadata: getCatalogData.old_value[`${formValues?.type?.old_value_metadataid}`]
          }
        })
        return ;
      }
      submitForm(formValues)
    },
    [form, validateForm, getCatalogDataRequest]
  );

  const {
    manual_keys: manualKey,
    dataobject_info: dataObjectInfo,
    validation_failure_reason: reason,
    downstream,
    change_type: changeType,
    old_value: oldValue,
  } = getCatalogData;

  const { getFieldValue, getFieldDecorator } = form;

  return (
    <LayoutContentWrapper className="referral-table">
      <CatalogWrapper>
        <Spin
          spinning={isLoading || !!GET_CATALOG_LOADER}
        >
          {renderIdForm ? (
            <GetIdForm
              getCatalogDataRequest={getCatalogDataRequest}
              loading={!!GET_CATALOG_LOADER || !!isLoading}
            />
          ) : (
            <div className="form">
              <section className="form__header">
                <h1>Data Catalog Form</h1>
                  {reason && <p> Validation Failure Reason : {reason} </p>}
              </section>

              <section className="form__container">
                <Form onSubmit={handleSubmit}>
                  <section className="form__section">
                    <section className="form__objinfo">
                      <p className="bold"> Data Object Information : </p>

                      <div className="form__obj">
                        {getFormItems.call(this, {
                          form,
                          formName: "dataobject_name",
                          type: "String",
                          required: true,
                          label: "Data Object Name : ",
                          initialValue: dataObjectInfo?.dataobject_name,
                          disableField: true,
                          className:"darkfield",
                        })}
                      </div>

                      <div className="form__obj">
                        {getFormItems.call(this, {
                          form,
                          formName: "dataobj_source",
                          type: "String",
                          required: true,
                          label: "Data Object Source : ",
                          initialValue: dataObjectInfo?.dataobj_source,
                          disableField: true,
                          className:"darkfield",
                        })}
                      </div>

                      <div className="form__obj">
                        {getFormItems.call(this, {
                          form,
                          formName: "dataobject_type",
                          type: "String",
                          required: true,
                          label: "Data Object Type : ",
                          initialValue: dataObjectInfo?.dataobject_type,
                          disableField: true,
                          className:"darkfield",
                        })}
                      </div>
                    </section>

                    {downstream  && Object.keys(downstream).length && (
                      <section className="form__downstream">
                        <p className="bold"> Downstream : </p>
                        {Object.keys(downstream).map((item, idx) => (
                          <div key={idx} className="inner-section">
                            {getFormItems.call(this, {
                              form,
                              formName: `downstream.${item}`,
                              type: "multi-choices",
                              required: false,
                              options: downstream[`${item}`],
                              label: decorateLabel(item),
                              disableField: true,
                              initialValue: downstream[`${item}`],
                              className:"darkfield",
                            })}
                          </div>
                        ))}
                      </section>
                    )}
                  </section>

                  {changeType &&
                    Array.isArray(changeType) &&
                    changeType?.length && (
                      <section className="form__change-type">
                        <p className="bold"> Change Type : </p>
                        <div className="inner-section">
                          {getFormItems.call(this, {
                            form,
                            formName: "type.change_type",
                            type: "radio",
                            required: true,
                            className: "small-size",
                            options: changeType,
                            initialValue: "NewlyAdded"
                          })}
                        </div>

                        {getFieldValue("type.change_type") === "Renamed" &&
                          oldValue && (
                            <>
                            <div className="inner-section">
                                <p className="bold">Select Old Values : </p>
                                <div className="inner-section">
                                {
                                  <Form.Item>
                                    {getFieldDecorator('type.old_value_metadataid', {
                                      rules: [
                                        {
                                          required: true,
                                          message: "Select the Type of Value",
                                        },
                                      ],
                                    })(
                                      <Select
                                        showSearch
                                        allowClear
                                        dropdownMatchSelectWidth={false}
                                        filterOption={(input, option) =>
                                          option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                                      >
                                        {
                                           Object.keys(oldValue).map((item, idx) =>
                                             <Select.Option value={Number(item)} key={idx}>
                                               {oldValue[item]}
                                            </Select.Option>)
                                        }
                                      </Select>
                                    )}
                                  </Form.Item>
                                }
                                </div>
                              </div>
                            </>
                          )}
                      </section>
                    )}

                  {manualKey && (
                    <section className="form__manual-key">
                      <p className="bold"> Manual Keys : </p>
                      {Object.keys(manualKey).map((item, idx) => {
                        const data = getFormItems.call(this, {
                          form,
                          formName: `manual_key.${item}`,
                          type: manualKey[`${item}`].data_type,
                          required: manualKey[`${item}`].is_required,
                          className: "small-size",
                          label: decorateLabel(item),
                          initialValue: manualKey[`${item}`].value,
                        })
                        
                        
                      return (
                        <div key={idx} className="inner-section">
                          {data}
                        </div>
                      )})}
                    </section>
                  )}
                 
                 
              
                  <section className="form__btn">
                    <Button type="primary" htmlType="submit">
                      Submit
                    </Button>
                  </section>
                </Form>
              </section>
            </div>
          )}
        </Spin>
      </CatalogWrapper>
    </LayoutContentWrapper>
  );
}

const WrappedForm = Form.create({})(DataCatalogForm);

export default WrappedForm;
