import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const CatalogContext = createContext()

export const CatalogContextProvider = (props) => {
  return (
    <CatalogContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </CatalogContext.Provider>
  )
}

export const useCatalogContextValue = () => useContext(CatalogContext)
