import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCatalogContextValue } from '../../context'
import { ACTIONS } from '../actions'

export const useCatalogServiceCall = (actionsCall = () => { }) => {
  const [catalogState, dispatch] = useCatalogContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(
      actionsCall({
        ...payload
      })
    )
  }

  return [catalogState, request]
}

export const useGetCatalogData = () => {
  return useCatalogServiceCall(ACTIONS.getCatalogData)
}

export const useSubmitCatalog = () => {
  return useCatalogServiceCall(ACTIONS.submitCatalog)
}

export const useResetState = () => {
  const [, dispatch] = useCatalogContextValue()
  const resetState = (keys = []) => {
    dispatch(ACTIONS.resetReduxStateCatalog(keys))
  }
  return [resetState]
}
