import React, { useCallback } from 'react';
import FormWrapper from './index.style';
import { Button, Form, Input } from 'antd'

const GetIdForm = ({ form, getCatalogDataRequest }) => {

  const { getFieldDecorator } = form

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }, [form])

  const handleSubmit = useCallback(async (e) => {
    e.preventDefault()
    const valid = await validateForm()
    if (!valid) return
    const formValues = {
      ...form.getFieldsValue()
    }

    getCatalogDataRequest({
      query: {
        meta_data: formValues?.meta_id,
        validation_id: formValues?.validation_id,
      }
    })
  }, [form, validateForm, getCatalogDataRequest])

  return (
    <FormWrapper>
      <div className='form'>
        <h2 className='form__heading'>Data Catalog ID Form</h2>

        <Form onSubmit={handleSubmit}>
          <section className='form__container'>
            <label>Validation Id</label>
            <Form.Item>
              {getFieldDecorator("validation_id", {
                rules: [{ required: true, message: "Please enter Validation Id" }]
              })(
                <Input 
                  type="number"
                  placeholder='Validation Id'
                />
              )}
            </Form.Item>
          </section>

          <section className='form__container'>
            <label>Meta-Data Id</label>
            <Form.Item>
              {getFieldDecorator("meta_id", {
                rules: [{ required: true, message: "Please enter Meta-Data Id" }]
              })(
                <Input
                  type="number"
                  placeholder='MetaData Id'
                />
              )}
            </Form.Item>
          </section>

          <section className='form__btn-container'>
            <Button 
              htmlType='submit' 
              type='primary'
              className=''
            >
              Submit
            </Button>
          </section>

        </Form>

      </div>
    </FormWrapper>
  )
}

const WrappedForm = Form.create({})(GetIdForm)


export default WrappedForm