import urls from '../../../../config/urls'
const configUrl = urls.url

export const ACTIONS = {
  GET_CATALOG: 'GET_CATALOG',
  GET_CATALOG_REQUEST: 'GET_CATALOG_REQUEST',

  SUBMIT_CATALOG: 'SUBMIT_CATALOG',
  SUBMIT_CATALOG_REQUEST: 'SUBMIT_CATALOG_REQUEST',

  RESET_REDUX_STATE_CATALOG: 'RESET_REDUX_STATE_CATALOG',

  getCatalogData: (payload) => ({
    type: ACTIONS.GET_CATALOG_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getCatalogData
    }
  }),

  submitCatalog: (payload) => ({
    type: ACTIONS.SUBMIT_CATALOG_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.submitDataCatalog
    }
  }),

  resetReduxStateCatalog: (keys) => ({
    type: ACTIONS.RESET_REDUX_STATE_CATALOG,
    payload: keys
  })
}
